-- 조건: 보너스 목표는 battlebonus 의 koSBDone(줄, 목표). 줄 번호는 bonus_data 의 ev=130
local function w1BonusDone()
	local f=rawget(_G,"koSBDone")
	if not f then return false end
	local ok,t=pcall(dofile,CONFIG.koCampScript.."bonus_data.lua")
	if not ok or type(t)~="table" then return false end
	for i,e in ipairs(t) do
		if e.ev==130 then return f(i,1) or f(i,2) end
	end
	return false
end
local function w1Ok()
	if w1BonusDone() then return true end
	return JY.Person[1][W1_LV]>=JY.Person[W1_LU][W1_LV]-5
end
-- 합류: 적토마는 들고 오지 않음 (사건 323 에서 주움)
local function w1Join()
	koIfSetVal(245,30)
	ModifyForce(W1_LU,1)
	local P=JY.Person[W1_LU]
	local t={}
	for i=1,8 do local v=P[W1_ITEM..i] or 0 if v>0 and v~=8 then t[#t+1]=v end end
	for i=1,8 do P[W1_ITEM..i]=t[i] or 0 end
end
local function w1Trust()
	if not koIfOn() or koIfChoice(1)~=2 or koIfDoneOf(1) then return end
	if JY.Person[W1_LU][W1_LORD]~=1 then return end
	local d=-3
	for i=1,War.PersonNum or 0 do
		local v=War.Person[i]
		if v and v.id==W1_LU and not v.enemy then d=v.live and 10 or -15 break end
	end
	koIfSetVal(245,math.max(0,math.min(99,koIfVal(245)+d)))
	-- 11-04 사용자 「신뢰는 어떻게 확인해」: 전투 끝마다 수치를 보여 줌 (관도 시험 뒤에는 위에서 돌아감)
	local why=(d==10) and "\137\072\138\095 \137\106\132\069 \129\071\141\091 +10" or ((d==-15) and "\129\098\134\097\129\094 \133\068\130\069\137\072 -15" or "\133\098\129\103\129\097\130\067 \130\107\130\077 -3")
	WarDrawStrBoxConfirm("\129\098\134\097\131\080 \131\078\132\098 "..koIfVal(245).." / 50*"..why.."*\129\101\129\068 \130\066\132\101 \130\066\129\089\130\067 50 \129\071 \130\111 \132\067\129\065 \139\088\139\095\129\076\129\077.",M_White,true)
end
koOn("war_won",w1Trust)
