--  그때 원래 칸을 본떠 채움) 빈손 새 칸으로 들어오던 것 → 떠난 원래 칸의 레벨 · 경험치 · 병종 · 장비 · 도구를 사본이 이어받음.
--  ModifyForce 를 감쌈 (이야기 애드온은 기본 애드온 뒤에 실려 이 감싸기가 가장 바깥 → 옮긴 뒤 gear · storyhire 등 안쪽 감싸기)
do
	local W1_NAME="\208\213\195\251"   -- 姓名
	local W1_EXP,W1_BZ="\190\173\209\233","\177\248\214\214"   -- 经验 兵种
	local W1_GEAR={"\206\228\198\247","\183\192\190\223","\184\168\214\250"}   -- 武器 防具 辅助
	local mf=rawget(_G,"ModifyForce")
	if type(mf)=="function" then
		function ModifyForce(pid,fid,...)
			if (fid or 1)==1 and pid and pid>=421 and pid<=530 and pid<JY.PersonNum and koIfOn() and koIfChoice(1)==2
				and JY.Person[pid][W1_LORD]~=1 then
				for _,o in ipairs({W1_LU,W1_GO}) do
					local P,C=JY.Person[o],JY.Person[pid]
					if P[W1_LORD]~=1 and P[W1_NAME]==C[W1_NAME] then
						if P[W1_LV]>=C[W1_LV] then C[W1_LV]=P[W1_LV] C[W1_EXP]=P[W1_EXP] C[W1_BZ]=P[W1_BZ] end
						for _,k in ipairs(W1_GEAR) do if (P[k] or 0)>0 then C[k]=P[k] P[k]=0 end end
						local u,seen={},{}
						for i=1,8 do local v=P[W1_ITEM..i] or 0 if v>0 and not seen[v] then u[#u+1]=v seen[v]=true end P[W1_ITEM..i]=0 end
						for i=1,8 do local v=C[W1_ITEM..i] or 0 if v>0 and not seen[v] and #u<8 then u[#u+1]=v seen[v]=true end end
						for i=1,8 do C[W1_ITEM..i]=u[i] or 0 end
						if rawget(_G,"koAddonLog") then koAddonLog("ifcamp wuje: tavern "..pid.." takes over "..o) end
						break
					end
				end
			end
			return mf(pid,fid,...)
		end
	end
end

-- 11-14 (cafe report: two Go Sun): a tavern copy (421~530) hired first, then the IF brings the real Lu Bu (5) / Go Sun (236)
--  -> the real record takes the copy's level / exp / class (the higher level wins), and its items (bag first, the rest to the
--  storehouse); the copy steps down, so there is one of each. Saves that already hold both: done when a record is loaded.
do
	local NM="\208\213\195\251"                       -- name
	local EXP,BZ="\190\173\209\233","\177\248\214\214" -- exp, class
	local GEAR={"\206\228\198\247","\183\192\190\223","\184\168\214\250"}
	local function copyOf(o)
		for c=421,math.min(530,JY.PersonNum-1) do
			local C=JY.Person[c]
			if C[W1_LORD]==1 and C[NM]==JY.Person[o][NM] then return c end
		end
	end
	local function w1Merge(o)
		if not (koIfOn() and koIfChoice(1)==2) or JY.Person[o][W1_LORD]~=1 then return end
		local c=copyOf(o)
		if not c then return end
		local P,C=JY.Person[o],JY.Person[c]
		if C[W1_LV]>P[W1_LV] then P[W1_LV]=C[W1_LV] P[EXP]=C[EXP] P[BZ]=C[BZ] end
		local bag,rest={},{}
		for i=1,8 do local v=P[W1_ITEM..i] or 0 if v>0 then bag[#bag+1]=v end end
		for i=1,8 do local v=C[W1_ITEM..i] or 0 if v>0 then if #bag<8 then bag[#bag+1]=v else rest[#rest+1]=v end end C[W1_ITEM..i]=0 end
		for _,k in ipairs(GEAR) do C[k]=0 end
		for i=1,8 do P[W1_ITEM..i]=bag[i] or 0 end
		for _,v in ipairs(rest) do if not (rawget(_G,"koStorePut") and koStorePut(v)) then break end end
		ModifyForce(c,0)
		pcall(ReSetAttrib,o,false)
		if rawget(_G,"koAddonLog") then koAddonLog("ifcamp wuje: real "..o.." absorbs tavern copy "..c) end
	end
	local mf=rawget(_G,"ModifyForce")
	if type(mf)=="function" then
		function ModifyForce(pid,fid,...)
			local r=table.pack(mf(pid,fid,...))
			if (fid or 1)==1 and (pid==W1_LU or pid==W1_GO) then pcall(w1Merge,pid) end
			return table.unpack(r,1,r.n)
		end
	end
	local lr=rawget(_G,"LoadRecord")
	if type(lr)=="function" then
		function LoadRecord(id,...)
			local r=table.pack(lr(id,...))
			if id and id>0 then pcall(w1Merge,W1_LU) pcall(w1Merge,W1_GO) end
			return table.unpack(r,1,r.n)
		end
	end
end

-- 군웅록 11-16 (영걸전 카페 제보와 같은 일): W1 로 진짜 여포(5) · 고순(236)이 우리 편인 채 회차를 넘기면 koNG.reset 이 그 칸의
--  능력치(+경험) · 천부 · 특기(+도구 계승이면 가방)를 되살려, 다음 회차 처음부터 적으로 나오는 여포 · 고순이 그것을 들었다.
--  → 넘기기 직전: 같은 이름 술집 사본(421~530)에 기록을 통째로 옮겨 우리 편 사본처럼 이어받게 하고, 진짜 칸은 newgame 값으로.
--  → 이미 넘긴 세이브(2회차 이상, 이번 회차 IF 전, 적): 불러올 때 한 번 같은 일 (적이 원래 든 것은 남김).
--  사본 칸은 이름으로 찾음(주점에 한 번이라도 들러 사본이 채워졌을 때) — 없으면 그대로.
do
	local NM="\208\213\195\251"
	local LV,EXP,TRAIN="\181\200\188\182","\190\173\209\233","\208\222\193\182"
	local NFACE="\208\194\205\183\207\241\180\250\186\197"
	local GEAR={"\206\228\198\247","\183\192\190\223","\184\168\214\250"}
	local STAT={{"\206\228\193\166","\206\228\193\166\190\173\209\233"},{"\214\199\193\166","\214\199\193\166\190\173\209\233"},{"\205\179\194\202","\205\179\194\202\190\173\209\233"}}
	local TAL={"\204\236\184\179"} for k=1,6 do TAL[#TAL+1]="\204\216\188\188"..k end
	local REAL={[181]=4,[182]=5,[183]=10,[184]=11,[185]=12,[186]=13,[187]=14,[188]=15,[189]=16,[190]=58,[191]=59,[192]=60,[193]=61,[194]=62,[195]=63}
	local EVK="\202\194\188\254"
	local function base(i,k) return GetDataFromStruct(JY.Data_Person_Base,i*CC.PersonSize,CC.Person_S,k) end
	local function copySlot(o)
		for i=421,math.min(530,JY.PersonNum-1) do if JY.Person[i][NM]==JY.Person[o][NM] then return i end end
	end
	local function own(o,v)
		for i=1,8 do local b=base(o,W1_ITEM..i) if b>0 then if b==v then return true end local r=REAL[b] if r and ((rawget(_G,"koGearMove") or {})[r] or r)==v then return true end end end
		local gi=rawget(_G,"koGearIndexT") local k=gi and gi(JY.Person[o][NM])
		return k~=nil and koGearData~=nil and koGearData[k]~=nil and koGearData[k][2]==v
	end
	local function toBase(o,keepOwn)
		local P=JY.Person[o]
		for _,f in ipairs(STAT) do P[f[1]]=base(o,f[1]) P[f[2]]=base(o,f[2]) end
		for _,f in ipairs(TAL) do P[f]=base(o,f) end
		if keepOwn then
			local u={}
			for i=1,8 do local v=P[W1_ITEM..i] or 0 if v>0 and own(o,v) then u[#u+1]=v end end
			for i=1,8 do P[W1_ITEM..i]=u[i] or 0 end
		else
			for i=1,8 do P[W1_ITEM..i]=base(o,W1_ITEM..i) end
		end
		for _,k in ipairs(GEAR) do P[k]=0 end
	end
	local function grown(o)
		local P=JY.Person[o]
		for _,f in ipairs(STAT) do if (P[f[2]] or 0)~=base(o,f[2]) then return true end end
		for _,f in ipairs(TAL) do if (P[f] or 0)~=base(o,f) then return true end end
		return false
	end
	local function cycleOut()
		if not JY.Data_Person_Base or (JY.PersonNum or 0)<=530 then return end
		for _,o in ipairs({W1_LU,W1_GO}) do
			local P=JY.Person[o]
			local c=P[W1_LORD]==1 and copySlot(o)
			if c and JY.Person[c][W1_LORD]~=1 then
				local C=JY.Person[c]
				for k,_ in pairs(CC.Person_S) do C[k]=P[k] end
				C[W1_LORD]=1
				toBase(o,false)
				if rawget(_G,"koAddonLog") then koAddonLog("ifcamp wuje: cycle - "..o.." handed to tavern copy "..c) end
			end
		end
	end
	local function cycleRetro()
		if not JY.Data_Person_Base or (JY.PersonNum or 0)<=530 or JY.Status==GAME_WMAP or CC.koFree or CC.koReplay then return end
		if (CC.koNG and CC.koNG.rcycle and CC.koNG.rcycle() or 1)<2 or koIfChoice(1)==2 then return end
		for _,o in ipairs({W1_LU,W1_GO}) do
			local P=JY.Person[o]
			local c=(P[W1_LORD]~=1 and grown(o)) and copySlot(o)
			if c and JY.Person[c][W1_LORD]~=1 then
				local C=JY.Person[c]
				local moved={}
				for i=1,8 do local v=P[W1_ITEM..i] or 0 if v>0 and not own(o,v) then moved[#moved+1]=v end end
				local f=1870+c-420
				if (JY.Base[EVK..f] or 0)>0 then
					for _,s in ipairs(STAT) do if (P[s[1]] or 0)>(C[s[1]] or 0) then C[s[1]]=P[s[1]] C[s[2]]=P[s[2]] end end
					for _,s in ipairs(TAL) do C[s]=P[s] end
					for _,v in ipairs(moved) do
						local put=false
						for i=1,8 do if (C[W1_ITEM..i] or 0)==0 then C[W1_ITEM..i]=v put=true break end end
						if not put and rawget(_G,"koStorePut") then koStorePut(v) end
					end
				else
					for k,_ in pairs(CC.Person_S) do C[k]=P[k] end
					C[LV]=1 C[EXP]=0 C[TRAIN]=0 C[W1_LORD]=0 C[NFACE]=0
					for i=1,8 do C[W1_ITEM..i]=moved[i] or 0 end
					for _,k in ipairs(GEAR) do C[k]=0 end
					JY.Base[EVK..f]=1
				end
				toBase(o,true)
				pcall(ReSetAttrib,c,true) pcall(ReSetAttrib,o,true)
				if rawget(_G,"koAddonLog") then koAddonLog("ifcamp wuje: retro - "..o.." growth moved to tavern copy "..c) end
			end
		end
	end
	function koWjCycleT(retro) if retro then return cycleRetro() end return cycleOut() end-- for test scripts
	local NG=CC.koNG
	if type(NG)=="table" and type(NG.reset)=="function" then
		local rawReset=NG.reset
		NG.reset=function(...)
			pcall(cycleOut)
			return rawReset(...)
		end
	end
	local lr=rawget(_G,"LoadRecord")
	if type(lr)=="function" then
		function LoadRecord(id,...)
			local r=table.pack(lr(id,...))
			if id and id>0 then local ok,err=pcall(cycleRetro) if not ok and rawget(_G,"koAddonLog") then koAddonLog("ifcamp wuje retro: "..tostring(err)) end end
			return table.unpack(r,1,r.n)
		end
	end
end

