-- ---------------------------------------------------------------- 뒤 장면: 유비 쪽 관우 자리 바꾸기
-- 사건 안에서만 인물을 바꿔 부름. map[인물]=다른 인물 / false(부르지 않음). opt.drop[인물]=true: SnrAdd 안 함. opt.leader[n]=m: SnrSetAllies 둘째 인자
local function w2Person(ev,map,opt)
	opt=opt or {}
	koIfWrap(ev,function(orig,...)
		if not koIfAct(2) then return orig(...) end
		local T,WS,WH,SA,SL,SS=talk,WarShowArmy,SnrWarHide,SnrAdd,SnrLeave,SnrSetAllies
		talk=function(...)
			local a={...}
			for i=1,select("#",...),2 do if map[a[i]] then a[i]=map[a[i]] end end
			return T(table.unpack(a,1,select("#",...)))
		end
		WarShowArmy=function(n)
			local m=map[n+1]
			if m==false then return end
			return WS((m or (n+1))-1)
		end
		SnrWarHide=function(p)
			local m=map[p]
			if m==false then return end
			return WH(m or p)
		end
		SnrAdd=function(p,...)
			if opt.drop and opt.drop[p] then return end
			local m=map[p]
			if m==false then return end
			return SA(m or p,...)
		end
		SnrLeave=function(list,...)
			local o,seen={},{}
			for _,p in ipairs(list) do
				local m=map[p]
				if m~=false then
					local q=m or p
					if not seen[q] then seen[q]=true o[#o+1]=q end
				end
			end
			return SL(o,...)
		end
		SnrSetAllies=function(t,l,list)
			return SS(t,(opt.leader and opt.leader[l]) or l,list)
		end
		local r={pcall(orig,...)}
		talk,WarShowArmy,SnrWarHide,SnrAdd,SnrLeave,SnrSetAllies=T,WS,WH,SA,SL,SS
		if not r[1] then error(r[2],0) end
		return table.unpack(r,2)
	end)
end
local function w2Drop(list) koIfRowDrop(list,66) end

